import{z as p,x as E,o as r,c,q as o,j as s,D as t,d as l,s as i,S as d,b as a}from"./chunks/framework.C8m1ZpeB.js";const D=JSON.parse('{"title":"双向与循环链表","description":"","frontmatter":{"title":"双向与循环链表","date":"2026-09-08T00:00:00.000Z","section":"cs"},"headers":[],"relativePath":"cs/dll-circular.md","filePath":"cs/dll-circular.md","lastUpdated":1791063341000}'),A={name:"cs/dll-circular.md"};function B(u,e,h,m,x,C){const n=E("Mermaid");return r(),c("div",null,[e[2]||(e[2]=o('<h1 id="双向与循环链表" tabindex="-1">双向与循环链表 <a class="header-anchor" href="#双向与循环链表" aria-label="Permalink to &quot;双向与循环链表&quot;">​</a></h1><div class="epigraph"><p>再加一条前驱指针，删除就不必先找上一节点；把头尾接成环，空表与单节点用同一套绕接规则。</p><footer>—— 据 Knuth, The Art of Computer Programming 卷 1；Cormen, Leiserson, Rivest and Stein 整理</footer></div><p><a href="/cs/linked-list-locality">上一课</a>以单向链表为主，点名双向用再一个指针换前驱，并强调指针追逐的局部性代价。本课不重讲「插入改两三条边」。缺口是把双向与循环写成可用的表示：已知节点删除 \\(\\Theta(1)\\)、反向遍历、以及哨兵/环降低空表分支。栈课立刻要用「序列的两种表示」；本课把链表这一侧收齐。</p><h2 id="问题" tabindex="-1">问题 <a class="header-anchor" href="#问题" aria-label="Permalink to &quot;问题&quot;">​</a></h2><p>单向删除若只知道被删节点，找不到前驱，必须从头扫，合同退化成 \\(\\Theta(n)\\)。操作系统与内核队列经常「从任意节点摘下」。缺口不是新的 ADT，而是节点 <code>{prev, next, 值}</code> 的不变式：<code>x.next.prev = x</code>（在非空双向表上）。循环：最后一个 <code>next</code> 指向头（或哨兵），避免 <code>tail.next</code> 为空的特殊情况。</p><p>局部性不会因此变好：多一个指针，节点更大，cache 行装更少。本课承认这笔常数，不把链表改回数组。</p><p><span class="marginnote">数字实例：设每个值 8 字节、每条指针 8 字节。单向节点 16 字节，一条 64 字节 cache 行能装 4 个；双向节点 24 字节，只能装 2 个还带零头。多出的前驱指针不只是「多 8 字节」，而是让每次指针跳跃更容易撞上一次真实的内存访问。</span></p><p><span class="marginnote">哨兵节点让空表也有一个真实对象，插入删除少写 <code>if head==null</code>。循环哨兵是 Knuth 卷 1 的常用手法。</span></p><h2 id="方法" tabindex="-1">方法 <a class="header-anchor" href="#方法" aria-label="Permalink to &quot;方法&quot;">​</a></h2><p>双向插入在已知 <code>p</code> 前或后：改四条边。删除 <code>x</code>：<code>x.prev.next = x.next</code>，<code>x.next.prev = x.prev</code>。循环：用哨兵 \\(s\\)，\\(s.next\\) 为真头，\\(s.prev\\) 为真尾；空表 \\(s.next=s.prev=s\\)。</p>',10)),(r(),s(d,null,{default:t(()=>[i(n,{id:"mermaid-28",class:"mermaid",graph:"flowchart%20LR%0A%20%20S%5B%22%E5%93%A8%E5%85%B5%22%5D%20--%3E%20A%5B%22a%22%5D%0A%20%20A%20--%3E%20B%5B%22b%22%5D%0A%20%20B%20--%3E%20S%0A%20%20S%20-.-%3E%7C%22prev%22%7C%20B%0A%20%20B%20-.-%3E%7C%22prev%22%7C%20A%0A%20%20A%20-.-%3E%7C%22prev%22%7C%20S%0A"})]),fallback:t(()=>[...e[0]||(e[0]=[l(" Loading... ",-1)])]),_:1})),e[3]||(e[3]=a("p",null,"遍历终止：走回哨兵，不要用空指针当结束（环上没有空）。",-1)),e[4]||(e[4]=a("p",null,[a("span",{class:"marginnote"},[l("常见误区：在环上写 "),a("code",null,"while (p != null)"),l(" 会永远转圈——环里根本没有 null。正确姿势是记下出发点，写成 "),a("code",null,"do { 访问 p; p = p.next } while (p != 起点)"),l("，或者干脆以哨兵为界：走到哨兵就停。")])],-1)),e[5]||(e[5]=a("h2",{id:"机制",tabindex:"-1"},[l("机制 "),a("a",{class:"header-anchor",href:"#机制","aria-label":'Permalink to "机制"'},"​")],-1)),e[6]||(e[6]=a("p",null,"合同仍是序列，端点操作与中间操作都可 \\(\\Theta(1)\\) 步（位置已知）。按下标仍 \\(\\Theta(i)\\)。与动态数组分工不变：要随机访问用数组；要任意位置摘挂用双向链。",-1)),(r(),s(d,null,{default:t(()=>[i(n,{id:"mermaid-41",class:"mermaid",graph:"flowchart%20TD%0A%20%20X%5B%22%E6%89%8B%E9%87%8C%E5%8F%AA%E6%9C%89%E8%A2%AB%E5%88%A0%E8%8A%82%E7%82%B9%20x%22%5D%20--%3E%20S1%5B%22%E5%8D%95%E5%90%91%E8%A1%A8%EF%BC%9A%E5%89%8D%E9%A9%B1%E6%9C%AA%E7%9F%A5%22%5D%0A%20%20S1%20--%3E%20S2%5B%22%E5%8F%AA%E8%83%BD%E4%BB%8E%E5%A4%B4%E6%89%AB%E6%8F%8F%E6%89%BE%E5%89%8D%E9%A9%B1%EF%BC%8C%CE%98(n)%22%5D%0A%20%20X%20--%3E%20D1%5B%22%E5%8F%8C%E5%90%91%E8%A1%A8%EF%BC%9Ax.prev%20%E5%B0%B1%E6%98%AF%E5%89%8D%E9%A9%B1%22%5D%0A%20%20D1%20--%3E%20D2%5B%22%E6%94%B9%E4%B8%A4%E6%9D%A1%E8%BE%B9%E5%8D%B3%E6%91%98%E4%B8%8B%EF%BC%8C%CE%98(1)%22%5D%0A"})]),fallback:t(()=>[...e[1]||(e[1]=[l(" Loading... ",-1)])]),_:1})),e[7]||(e[7]=o('<p>循环在轮转调度、约瑟夫环一类「到尾接回头」的轨迹上少一次分支。正确性靠不变式而不是靠「最后一个节点的 next 为 null」这种单向习惯。</p><p><span class="marginnote">术语翻译：「哨兵」就是一个不装业务数据的假节点，永远站在表头外。空表时 s.next = s.prev = s（指向自己），于是「表空」「只有一个元素」「有千万个元素」走同一套插入删除代码，不必为边界各写一份。</span></p><h2 id="边界" tabindex="-1">边界 <a class="header-anchor" href="#边界" aria-label="Permalink to &quot;边界&quot;">​</a></h2><p>本课不引入 XOR 链表压缩前后指针，不写无锁 CAS 环。也不把循环双向表当成队列的唯一实现——队列课会再用数组环形。跳表的多层前向指针是另一课。</p><p>后课默认：序列的链表表示可以是双向、可循环、可带哨兵。栈把操作收到一端，数组顶或链表头均可。</p><h2 id="小结" tabindex="-1">小结 <a class="header-anchor" href="#小结" aria-label="Permalink to &quot;小结&quot;">​</a></h2><ul><li>双向：已知节点删除 \\(\\Theta(1)\\)，可反向走。</li><li>循环加哨兵：空与非空同一套绕接。</li><li>局部性仍差；栈下一课收窄到 LIFO。</li><li>出处：Knuth, <em>TAOCP</em> 卷 1；Cormen et al. 双向链表。</li></ul>',7))])}const T=p(A,[["render",B]]);export{D as __pageData,T as default};
